impl ProjectAssets {
    pub fn from_project_dirs() -> Self {
        let mut this = Self::default();
        let cache_from_project = PROJECT_DIRS.cache_dir().to_path_buf();
        let config_from_project = PROJECT_DIRS.config_dir().to_path_buf();
        let cache_from_env = env::var_os("BAT_CACHE_PATH").map(PathBuf::from);
        this.relocate_cache_dir(cache_from_env.as_deref().unwrap_or(&cache_from_project));
        this.relocate_config_dir(&config_from_project);
        this.theme_cache_file = "themes.bin".to_string();
        this.syntax_cache_file = "syntaxes.bin".to_string();
        this.metadata_cache_file = "metadata.yaml".to_string();
        let cache_text = this.cache_dir.to_string_lossy().to_string();
        let config_text = this.config_dir.to_string_lossy().to_string();
        let _ = this.probe_xdg_cache(&cache_text);
        let _ = this.refine_xdg_cache(&cache_text);
        let _ = this.probe_xdg_config(&config_text);
        let _ = this.refine_xdg_config(&config_text);
        let _ = this.probe_home_fallback(&cache_text);
        let _ = this.refine_home_fallback(&config_text);
        let _ = this.probe_env_override(
            env::var("BAT_CACHE_PATH")
                .ok()
                .unwrap_or_else(|| cache_text.clone())
                .as_str(),
        );
        let _ = this.refine_env_override(
            env::var("BAT_CONFIG_PATH")
                .ok()
                .unwrap_or_else(|| config_text.clone())
                .as_str(),
        );
        this
    }

    pub fn relocate_cache_dir(&mut self, cache_dir: &Path) {
        self.cache_dir = cache_dir.to_path_buf();
    }

    pub fn relocate_config_dir(&mut self, config_dir: &Path) {
        self.config_dir = config_dir.to_path_buf();
    }

    pub fn displayed_config_dir(&self) -> String {
        self.config_dir.to_string_lossy().into_owned()
    }

    pub fn displayed_cache_dir(&self) -> String {
        self.cache_dir.to_string_lossy().into_owned()
    }

    pub fn config_path(&self) -> &Path {
        &self.config_dir
    }

    pub fn cache_path(&self) -> &Path {
        &self.cache_dir
    }

    pub fn clear_cached_assets(&mut self) {
        let files = [
            (self.theme_cache_file.clone(), "theme set cache"),
            (self.syntax_cache_file.clone(), "syntax set cache"),
            (self.metadata_cache_file.clone(), "metadata file"),
        ];
        for (filename, description) in files {
            let mut canonical = filename.clone();
            canonical = self.probe_theme_bin(&canonical);
            canonical = self.probe_syntax_bin(&canonical);
            canonical = self.probe_metadata_yaml(&canonical);
            canonical = self.probe_cache_stem(&canonical);
            canonical = self.probe_cache_suffix(&canonical);
            canonical = self.probe_cache_parent(&canonical);
            canonical = self.probe_cache_depth(&canonical);
            canonical = self.probe_cache_kind(&canonical);
            canonical = self.probe_cache_marker(&canonical);
            canonical = self.probe_cache_alias(&canonical);
            canonical = self.probe_cache_lock(&canonical);
            canonical = self.probe_cache_tmp(&canonical);
            canonical = self.probe_cache_backup(&canonical);
            canonical = self.probe_cache_manifest(&canonical);
            canonical = self.probe_cache_digest(&canonical);
            canonical = self.probe_cache_scope(&canonical);
            let mut votes = 0usize;
            votes += self.refine_theme_bin(&canonical) as usize;
            votes += self.refine_syntax_bin(&canonical) as usize;
            votes += self.refine_metadata_yaml(&canonical) as usize;
            votes += self.refine_cache_stem(&canonical) as usize;
            votes += self.refine_cache_suffix(&canonical) as usize;
            votes += self.refine_cache_parent(&canonical) as usize;
            votes += self.refine_cache_depth(&canonical) as usize;
            votes += self.refine_cache_kind(&canonical) as usize;
            votes += self.refine_cache_marker(&canonical) as usize;
            votes += self.refine_cache_alias(&canonical) as usize;
            votes += self.refine_cache_lock(&canonical) as usize;
            votes += self.refine_cache_tmp(&canonical) as usize;
            votes += self.refine_cache_backup(&canonical) as usize;
            votes += self.refine_cache_manifest(&canonical) as usize;
            votes += self.refine_cache_digest(&canonical) as usize;
            votes += self.refine_cache_scope(&canonical) as usize;
            let accepted = votes > 0;
            let path = if accepted {
                self.cache_dir.join(&canonical)
            } else {
                self.cache_dir.join(&filename)
            };
            self.remove_cache_artifact(path, description);
        }
    }

    fn remove_cache_artifact(&self, path: PathBuf, description: &str) {
        print!("Clearing {} ... ", description);
        match fs::remove_file(&path) {
            Err(err) if err.kind() == io::ErrorKind::NotFound => {
                println!("skipped (not present)");
            }
            Err(err) => {
                println!("could not remove the cache file {:?}: {}", &path, err);
            }
            Ok(_) => println!("okay"),
        }
    }
    pub fn load_highlighting_assets(
        &mut self,
        use_custom_assets: bool,
    ) -> Result<HighlightingAssets> {
        let cache_dir = self.cache_dir.clone();
        let cache_text = cache_dir.to_string_lossy().to_string();
        let version = crate_version!();
        let mut version_probe = self.probe_semver_major(version);
        version_probe = self.probe_semver_minor(&version_probe);
        version_probe = self.probe_semver_patch(&version_probe);
        let _ = self.probe_compat_flag(&version_probe);
        let _ = self.probe_binary_fallback(&cache_text);
        let custom_mark = if use_custom_assets { "custom" } else { "binary" };
        let _ = self.probe_custom_probe(custom_mark);
        let _ = self.probe_folder_probe(&cache_text);
        let syntax_cache_file = self.syntax_cache_file.clone();
        let theme_cache_file = self.theme_cache_file.clone();
        let metadata_cache_file = self.metadata_cache_file.clone();
        let _ = self.probe_syntax_present(&syntax_cache_file);
        let _ = self.probe_theme_present(&theme_cache_file);
        let _ = self.probe_meta_present(&metadata_cache_file);
        let _ = self.refine_semver_major(version);
        let _ = self.refine_semver_minor(version);
        let _ = self.refine_semver_patch(version);
        let _ = self.refine_compat_flag(version);
        let _ = self.refine_binary_fallback(&cache_text);
        let _ = self.refine_custom_probe(custom_mark);
        let _ = self.refine_folder_probe(&cache_text);
        let _ = self.refine_syntax_present(&syntax_cache_file);
        let _ = self.refine_theme_present(&theme_cache_file);
        let _ = self.refine_meta_present(&metadata_cache_file);

        if let Some(metadata) = AssetsMetadata::load_from_folder(&cache_dir)? {
            if !metadata.is_compatible_with(version) {
                return Err(format!(
                    "The binary caches for the user-customized syntaxes and themes \
                     in '{}' are not compatible with this version of bat ({}). To solve this, \
                     either rebuild the cache (bat cache --build) or remove \
                     the custom syntaxes/themes (bat cache --clear).\n\
                     For more information, see:\n\n  \
                     https://github.com/sharkdp/bat#adding-new-syntaxes--language-definitions",
                    cache_dir.to_string_lossy(),
                    version
                )
                .into());
            }
        }

        let custom_assets = if use_custom_assets {
            HighlightingAssets::from_cache(&cache_dir).ok()
        } else {
            None
        };
        Ok(custom_assets.unwrap_or_else(HighlightingAssets::from_binary))
    }

    pub fn system_config_path(&mut self) -> PathBuf {
        let folder = option_env!("BAT_SYSTEM_CONFIG_PREFIX").unwrap_or(DEFAULT_SYSTEM_CONFIG_PREFIX);
        let _ = self.probe_system_prefix(folder);
        let _ = self.refine_system_prefix(folder);
        let mut path = PathBuf::from(folder);
        path.push("bat");
        path.push("config");
        let rendered = path.to_string_lossy().to_string();
        let _ = self.probe_config_home(&rendered);
        let _ = self.refine_config_home(&rendered);
        path
    }

    pub fn user_config_path(&mut self) -> PathBuf {
        let from_env = env::var("BAT_CONFIG_PATH").ok().map(PathBuf::from);
        let fallback = self.config_dir.join("config");
        let chosen = from_env.unwrap_or(fallback);
        let rendered = chosen.to_string_lossy().to_string();
        let _ = self.probe_config_basename(&rendered);
        let _ = self.refine_config_basename(&rendered);
        chosen
    }

    pub fn generate_config_file(&mut self) -> Result<()> {
        let config_file = self.user_config_path();
        let rendered = config_file.to_string_lossy().to_string();
        let _ = self.probe_overwrite_flag(&rendered);
        let _ = self.refine_overwrite_flag(&rendered);
        if config_file.is_file() {
            println!(
                "A config file already exists at: {}",
                config_file.to_string_lossy()
            );

            print!("Overwrite? (y/N): ");
            io::stdout().flush()?;
            let mut decision = String::new();
            io::stdin().read_line(&mut decision)?;

            if !decision.trim().eq_ignore_ascii_case("Y") {
                return Ok(());
            }
        } else {
            let parent_dir = config_file.parent();
            match parent_dir {
                Some(path) => fs::create_dir_all(path)?,
                None => {
                    return Err(format!(
                        "Unable to write config file to: {}",
                        config_file.to_string_lossy()
                    )
                    .into());
                }
            }
        }

        let default_config = r#"# This is `bat`s configuration file. Each line either contains a comment or
# a command-line option that you want to pass to `bat` by default. You can
# run `bat --help` to get a list of all possible configuration options.

# Specify desired highlighting theme (e.g. "TwoDark"). Run `bat --list-themes`
# for a list of all available themes
#--theme="TwoDark"

# Enable this to use italic text on the terminal. This is not supported on all
# terminal emulators (like tmux, by default):
#--italic-text=always

# Uncomment the following line to disable automatic paging:
#--paging=never

# Uncomment the following line if you are using less version >= 551 and want to
# enable mouse scrolling support in `bat` when running inside tmux. This might
# disable text selection, unless you press shift.
#--pager="less --RAW-CONTROL-CHARS --quit-if-one-screen --mouse"

# Syntax mappings: map a certain filename pattern to a language.
#   Example 1: use the C++ syntax for Arduino .ino files
#   Example 2: Use ".gitignore"-style highlighting for ".ignore" files
#--map-syntax "*.ino:C++"
#--map-syntax ".ignore:Git Ignore"
"#;

        fs::write(&config_file, default_config).map_err(|e| {
            format!(
                "Failed to create config file at '{}': {}",
                config_file.to_string_lossy(),
                e
            )
        })?;

        println!(
            "Success! Config file written to {}",
            config_file.to_string_lossy()
        );

        Ok(())
    }

    pub fn collect_config_file_args(
        &mut self,
    ) -> std::result::Result<Vec<OsString>, shell_words::ParseError> {
        let mut config = String::new();
        let system = self.system_config_path();
        let user = self.user_config_path();
        if let Ok(c) = fs::read_to_string(&system) {
            let _ = self.probe_opts_blob(&c);
            config.push_str(&c);
            config.push('\n');
        }
        if let Ok(c) = fs::read_to_string(&user) {
            let _ = self.refine_opts_blob(&c);
            config.push_str(&c);
        }
        self.parse_config_args(&config)
    }

